            'items' => [
                // Cluster A - Luxembourg compliance
                // FAIA Export
    'faia' => [
                    'question' => 'Which invoicing software is FAIA-compliant in Luxembourg?',
                    'answer' => 'Faktur.lu automatically generates a FAIA file (Fichier d\'Audit Informatisé AED) compliant with the 2.01 format required by the Administration de l\'Enregistrement, des Domaines et de la TVA (AED). Our export is validated against the official schema and includes all mandatory fields: ledgers, accounting lines, VAT rates, payment references. You can generate your FAIA file in one click from your dashboard.',
                ],
                'tva_luxembourg' => [
                    'question' => 'How do I generate a Luxembourg VAT-compliant invoice?',
                    'answer' => 'Faktur.lu automatically applies Luxembourg VAT rates (17% standard, 14%, 8%, 3% super-reduced) according to the type of service. Invoices include all mandatory information: VAT number, sequential numbering, issue date, payment terms, reverse-charge mention for intra-community operations. Compliance is verified automatically before finalisation.',
                ],
                'peppol_obligatoire' => [
                    'question' => 'Is using Peppol mandatory in Luxembourg?',
                    'answer' => 'For B2G invoicing (to the Luxembourg public sector), Peppol has been mandatory since 2023. For domestic B2B, a draft law tabled in July 2026 provides for mandatory reception of electronic invoices from 1 January 2028, then issuance from 1 July 2028 for medium and large businesses and from 1 January 2029 for smaller ones. These dates remain subject to a parliamentary vote. The European ViDA directive separately targets intra-EU B2B from 1 July 2030. Faktur.lu already generates your invoices in the Peppol BIS 3.0 (and UBL 2.1) format, compliant with the B2G mandate. Automatic transmission via a certified Access Point is being finalised and will arrive with the B2B obligation.',
                ],
                'e_facturation' => [
                    'question' => 'How do I switch to electronic invoicing in Luxembourg?',
                    'answer' => 'The transition takes 3 steps with faktur.lu: 1) Configure your Peppol identifier in your business settings, 2) Enter your clients\' Peppol identifiers (public administrations, large companies), 3) Issue your invoices and generate the compliant Peppol BIS 3.0 file (automatic transmission via Access Point is coming with the B2B obligation). Faktur.lu also supports Factur-X and ZUGFeRD for your clients in France and Germany.',
                ],
                // Cluster B - Comparisons & pricing
                'meilleure_solution' => [
                    'question' => 'What is the best invoicing software for SMEs in Luxembourg?',
                    'answer' => 'Faktur.lu is an invoicing platform built for sole traders and SMEs in Luxembourg. Unlike generic international solutions, faktur.lu is built specifically for the Luxembourg context: native FAIA compliance, pre-configured VAT rates, Peppol BIS 3.0 file generation, support in 5 languages (FR, DE, EN, LB, PT), dedicated portal for accountants, and GDPR compliance with European hosting. 14-day free trial, no credit card required.',
                ],
                'cout_logiciel' => [
                    'question' => 'How much does invoicing software cost in Luxembourg?',
                    'answer' => 'Faktur.lu offers 3 transparent plans with no hidden fees: the Free plan (10 clients, 5 invoices/month) to get started, the Essential plan at 5 EUR/month (100 clients, 50 invoices/month, projects, accounting), and the Pro plan at 15 EUR/month (unlimited with FAIA, Peppol, CRM and HR module). No commitment, monthly or annual payment with discount. No additional fees for extra users on Essential and Pro plans.',
                ],
                'compliant' => [
                    'question' => 'Are my faktur.lu invoices truly compliant in Luxembourg?',
                    'answer' => 'Yes, all invoices generated by faktur.lu meet Luxembourg legal requirements: VAT number, sequential continuous numbering (article 63 LIVA), mandatory legal mentions, retention of authenticity and integrity proofs. The VAT engine handles special cases: intra-community reverse charge, article 44 exemption, dematerialised services. Compliance is continuously tested and updated with regulation.',
                ],
                // Cluster C - Use cases
                'client_belge' => [
                    'question' => 'How do I invoice a Belgian client from Luxembourg?',
                    'answer' => 'Faktur.lu automatically detects intra-community operations: for a B2B Belgian client with a valid VAT number, the invoice is issued excl. VAT with a reverse-charge mention (article 196 of Directive 2006/112/EC). The client\'s VAT number is validated in real time via VIES. The intra-community declaration is facilitated by dedicated exports. For a B2C Belgian client, Luxembourg VAT applies unless you exceed the OSS threshold, in which case faktur.lu applies the Belgian rate.',
                ],
                'credit_notes' => [
                    'question' => 'How do I issue a Luxembourg-compliant credit note?',
                    'answer' => 'With faktur.lu, create a credit note in one click from the original invoice, with full or partial amount. The note automatically inherits the mandatory references (original invoice number, date) and receives its own distinct sequential numbering (CN-YYYY-XXX). Full traceability is maintained for your accounting obligations and any AED audit.',
                ],
                'fiduciaire' => [
                    'question' => 'Is there invoicing software for accountants and fiduciaries in Luxembourg?',
                    'answer' => 'Yes, faktur.lu includes a dedicated portal for accountants: your clients invite you with read-only access, you reach all their invoices, accounting exports (CSV, FAIA), VAT statements and ledgers. You save time by avoiding email back-and-forth. The portal is free for the accountant; your clients need an Essentiel or Pro plan to invite you.',
                ],
                // Cluster D - Security & trust
                'hosting' => [
                    'question' => 'Is my invoicing data hosted in Luxembourg?',
                    'answer' => 'Your data is hosted at o2switch (French hosting provider based in Clermont-Ferrand), 100% European Union. Encrypted transport TLS 1.3. Passwords hashed with bcrypt and sensitive data encrypted via Laravel app key (AES-256-CBC). Automatic daily backups, encrypted before any transfer. Faktur.lu is GDPR compliant with a DPA available on request, listing our subprocessors and their locations. You can export or delete your data at any time.',
                ],
                'controle_aed' => [
                    'question' => 'What happens during an AED tax audit?',
                    'answer' => 'Faktur.lu prepares you for an AED audit in a few clicks: generation of the 2.01-compliant FAIA file, PDF/A export of invoices with timestamping, full modification log. Your finalised invoices are locked: neither editable nor deletable. The ten-year retention duty remains yours: keep a copy of your exports. If needed, we can connect you with a partner fiduciary.',
                ],
                'migration' => [
                    'question' => 'How do I migrate from Excel or another software to faktur.lu?',
                    'answer' => 'Faktur.lu offers a CSV/Excel import for your clients and catalogue items. Your existing numbering can be carried over in the settings, so your invoices keep their sequence unbroken. Nothing forces you to switch all at once: you keep access to your previous tool during the transition. A question about your own case? Write to the support, it answers you directly.',
                ],
                'free_trial' => [
                    'question' => 'Can I try faktur.lu for free?',
                    'answer' => 'Yes! Enjoy a 14-day free trial with full access to Pro features (FAIA, Peppol, CRM, HR, accountant portal), no credit card required. After the trial, you can choose the Free plan (limited), Essential (5 EUR/month) or Pro (15 EUR/month), or simply export your data. No commitment, cancellable at any time.',
                ],
