    'glossary' => [
        'slug' => 'glossary',
        'page_title' => 'Glossary of Luxembourg invoicing and tax terms | faktur.lu',
        'meta_description' => 'FAIA, LIVA, AED, Peppol, ViDA, Article 56 ter, VIES… Clear definitions of every Luxembourg invoicing and VAT term for freelancers, SMEs and accountants.',
        'breadcrumb' => 'Glossary',
        'hero_title' => 'Luxembourg invoicing & tax glossary',
        'hero_subtitle' => 'Every technical, legal and regulatory term used in Luxembourg invoicing and taxation, explained clearly. FAIA, LIVA, AED, Peppol, ViDA and the other acronyms you keep meeting in your filings.',
        'set_name' => 'faktur.lu glossary - Luxembourg invoicing & taxation',
        'set_description' => 'Reference set of definitions for invoicing, VAT and tax compliance in Luxembourg: official LIVA terms, administrative abbreviations (AED, CCSS, RCS), standardised formats (FAIA, PDF/A, Factur-X, Peppol) and EU acronyms (VIES, OSS, ViDA).',
        'cta_title' => 'Compliant invoicing without memorising the rules',
        'cta_subtitle' => 'faktur.lu adds the right mandatory mentions automatically, validates VIES, generates FAIA and applies the right VAT rates. You no longer need to know every article by heart.',
        'cta_button' => 'Get started for free',
        'terms' => [
            'assujetti' => [
                'name' => 'Taxable person',
                'alternate' => 'VAT taxable person',
                'description' => 'Individual or legal entity that independently carries out an economic activity and is, on that basis, liable for VAT on its transactions. The taxable person charges VAT to customers and deducts it on purchases, unless covered by an exemption or franchise scheme.',
            ],
            'autofacturation' => [
                'name' => 'Self-billing',
                'alternate' => 'Autofacturation',
                'description' => 'Arrangement whereby the customer, rather than the supplier, issues the invoice in the supplier\'s name and on their behalf, based on a prior agreement. It remains subject to the same mandatory particulars and to the supplier\'s acceptance.',
            ],
            'bic' => [
                'name' => 'BIC',
                'alternate' => 'Bank Identifier Code (SWIFT)',
                'description' => 'International 8- or 11-character code identifying a bank in transfers. Together with the IBAN, it routes a SEPA or international payment to the right institution; Luxembourg banks carry the "LU" country code in positions 5 and 6.',
            ],
            'bon_de_commande' => [
                'name' => 'Purchase order',
                'alternate' => 'Customer order',
                'description' => 'Document by which a customer formalises an order with a supplier (products, quantities, agreed prices). It precedes the invoice and, once accepted, binds both parties; its number may be shown on the invoice to ease reconciliation.',
            ],
            'devis' => [
                'name' => 'Quote',
                'alternate' => 'Estimate',
                'description' => 'Dated, priced commercial proposal, valid for a set period, detailing the services and their price before any commitment. Once accepted and signed by the customer it acts as a contract and can be converted into an invoice.',
            ],
            'e_facturation' => [
                'name' => 'Electronic invoicing',
                'alternate' => 'E-invoicing',
                'description' => 'Issuing, transmitting and receiving invoices in a structured electronic format (not a plain PDF), enabling automated processing. In Luxembourg it is mandatory for the public sector via Peppol and will extend to B2B under the EU ViDA reform.',
            ],
            'escompte' => [
                'name' => 'Cash discount',
                'alternate' => 'Early-payment discount',
                'description' => 'Price reduction granted to a customer who pays before the due date. To be distinguished from a trade discount (remise): the cash discount rewards fast payment and must be shown separately on the invoice.',
            ],
            'facture_proforma' => [
                'name' => 'Proforma invoice',
                'alternate' => 'Proforma',
                'description' => 'Document that looks like an invoice but has no accounting or tax value, used to quote a price, obtain a down payment or accompany customs formalities. It does not generate VAT and does not replace the final invoice.',
            ],
            'facture_rectificative' => [
                'name' => 'Corrective invoice',
                'alternate' => 'Rectifying invoice',
                'description' => 'Invoice issued to correct a previous invoice containing an error (amount, VAT, particulars). It references the original invoice; when it reduces the amount, it often takes the form of a credit note.',
            ],
            'iban' => [
                'name' => 'IBAN',
                'alternate' => 'International Bank Account Number',
                'description' => 'Standardised international identifier of a bank account. In Luxembourg it has 20 characters starting with "LU" followed by a check key (MOD-97 validation, ISO 13616). It appears on invoices to enable payment by bank transfer.',
            ],
            'remise' => [
                'name' => 'Trade discount',
                'alternate' => 'Commercial rebate',
                'description' => 'Price reduction granted on a line or on the invoice total (commercial gesture, loyalty, volume). It lowers the taxable base: VAT is computed on the net amount after the discount. To be distinguished from the cash discount, which relates to the payment term.',
            ],
            'retenue_garantie' => [
                'name' => 'Retention guarantee',
                'alternate' => 'Performance retention',
                'description' => 'Portion of an invoice amount (often 5-10%) that a customer temporarily withholds, notably in construction, to secure proper completion of the works. It is released after acceptance or expiry of the warranty period.',
            ],
            'sepa' => [
                'name' => 'SEPA',
                'alternate' => 'Single Euro Payments Area',
                'description' => 'Single euro payments area that harmonises transfers and direct debits across the EU and a few associated countries. Thanks to SEPA, a transfer to a Luxembourg IBAN is made on the same terms as a domestic transfer.',
            ],
            'tva_deductible' => [
                'name' => 'Deductible VAT',
                'alternate' => 'Input VAT',
                'description' => 'VAT paid by a business on its professional purchases, which it can recover by deducting it from the VAT charged on its sales. Only the difference is paid to the administration. The right to deduct requires a compliant invoice and a business use.',
            ],
            'delai_paiement' => [
                'name' => 'Payment term',
                'alternate' => 'Payment due date',
                'description' => 'The period agreed to settle an invoice. Absent an agreement, the statutory term between businesses in Luxembourg is 30 days from receipt of the invoice or of the goods/services; beyond that, late-payment interest accrues automatically.',
            ],
            'exigibilite_tva' => [
                'name' => 'VAT chargeability',
                'alternate' => 'Chargeable event and chargeability',
                'description' => 'The moment when VAT becomes due to the administration and the customer\'s right to deduct arises. Depending on the scheme, VAT is chargeable upon supply or upon payment. Legal basis: article 21 LIVA (not to be confused with the reverse charge, governed by article 17).',
            ],
            'facture_acompte' => [
                'name' => 'Down-payment invoice',
                'alternate' => 'Advance invoice',
                'description' => 'Invoice issued for a partial payment received before delivery or completion of the service. It makes VAT chargeable on the amount received; the final invoice then deducts the down payments already invoiced.',
            ],
            'forme_juridique' => [
                'name' => 'Legal form',
                'alternate' => 'Business structure',
                'description' => 'The legal structure under which an activity is carried out in Luxembourg (sole proprietorship, SARL, SARL-S "one-euro company", SA, etc.). It determines the entrepreneur\'s liability, taxation and accounting obligations.',
            ],
            'interets_de_retard' => [
                'name' => 'Late-payment interest',
                'alternate' => 'Late fees',
                'description' => 'Interest owed by a customer who pays an invoice after the due date. Between businesses, Luxembourg law (transposing Directive 2011/7/EU) provides for the ECB reference rate plus 8 points, together with a flat EUR 40 recovery-costs compensation.',
            ],
            'mention_obligatoire' => [
                'name' => 'Mandatory particulars',
                'alternate' => 'Legal content of an invoice',
                'description' => 'The information every Luxembourg invoice must contain: identity and address of the parties, VAT numbers, date, sequential number, description, net base, VAT rate and amount, total. Legal basis: article 63 LIVA. An incomplete invoice may be rejected and expose the issuer to a fine.',
            ],
            'mise_en_demeure' => [
                'name' => 'Formal notice',
                'alternate' => 'Demand for payment',
                'description' => 'A formal letter demanding payment of an overdue invoice, generally a prerequisite before debt-recovery action. It may claim, in addition to the principal, late-payment interest and the flat recovery-costs compensation.',
            ],
            'numero_tva' => [
                'name' => 'VAT number',
                'alternate' => 'VAT identification number',
                'description' => 'Identifier assigned to a taxable person for VAT operations. In Luxembourg it takes the form "LU" followed by 8 digits. It must appear on invoices and be checked via VIES to apply the reverse charge to business customers in another member state.',
            ],
            'regime_normal_tva' => [
                'name' => 'Normal VAT scheme',
                'alternate' => 'VAT-registered scheme',
                'description' => 'Scheme under which the business charges VAT to its customers, deducts it on purchases and files periodic returns (monthly, quarterly or annually depending on turnover). It contrasts with the exemption scheme reserved for small turnovers.',
            ],
            'taux_tva' => [
                'name' => 'VAT rates (Luxembourg)',
                'alternate' => '17%, 14%, 8%, 3%',
                'description' => 'Luxembourg applies four VAT rates: 17% (standard), 14% (intermediate), 8% (reduced) and 3% (super-reduced). The rate depends on the nature of the good or service; Luxembourg\'s standard rate is the lowest in the European Union.',
            ],
            'tva_intracommunautaire' => [
                'name' => 'Intra-community VAT',
                'alternate' => 'Intra-EU transactions',
                'description' => 'VAT regime for supplies of goods and services between taxable persons in two EU member states. B2B services are generally invoiced without VAT (reverse charge by the customer), subject to a valid VAT number checked via VIES and a declaration in the recapitulative statement.',
            ],
            'access_point' => [
                'name' => 'Peppol Access Point',
                'alternate' => 'Point d\'accès Peppol',
                'description' => 'Certified provider that connects a business to the Peppol network to send and receive electronic invoices. Sender and receiver need not use the same access point: the Peppol "4-corner" model routes documents between them.',
            ],
            'acd' => [
                'name' => 'ACD',
                'alternate' => 'Luxembourg direct tax administration',
                'description' => 'Luxembourg tax authority responsible for direct taxes (personal income tax, corporate income tax, withholdings). Distinct from the AED, which handles VAT and the FAIA.',
            ],
            'archivage_legal' => [
                'name' => 'Legal archiving',
                'alternate' => 'Invoice retention (10 years)',
                'description' => 'Obligation to keep invoices and accounting records for 10 years in Luxembourg. Electronic retention (PDF/A recommended) is accepted provided integrity, legibility and accessibility are guaranteed for the whole period.',
            ],
            'b2g' => [
                'name' => 'B2G',
                'alternate' => 'Invoicing the public sector',
                'description' => 'Invoicing relationship between a business and a public body. In Luxembourg, electronic invoicing via Peppol is mandatory for public procurement (B2G); plain paper or PDF invoices are no longer accepted by contracting authorities.',
            ],
            'ecdf' => [
                'name' => 'eCDF',
                'alternate' => 'Electronic tax filing platform',
                'description' => 'Luxembourg financial-data collection platform for the electronic filing of tax returns and annual accounts, including VAT returns. Files must comply with the formats and schemas set by the administration.',
            ],
            'ioss' => [
                'name' => 'IOSS',
                'alternate' => 'Import One-Stop Shop',
                'description' => 'EU one-stop shop for declaring and paying VAT on distance sales of goods imported from third countries with a value not exceeding EUR 150. It simplifies import VAT collection for sellers and marketplaces.',
            ],
            'matricule' => [
                'name' => 'Matricule',
                'alternate' => 'Luxembourg national identification number',
                'description' => 'Unique identification number assigned in Luxembourg to individuals (13 digits) and to entities, used by social security and the tax administrations. A sole trader receives it upon registration and uses it in dealings with the CCSS, AED and ACD.',
            ],
            'note_de_credit' => [
                'name' => 'Credit note',
                'alternate' => 'Avoir',
                'description' => 'Document that cancels or reduces all or part of an already-issued invoice (error, return, discount, cancellation). It references the original invoice, carries its own sequential number and applies the same VAT as the corrected invoice.',
            ],
            'saf_t' => [
                'name' => 'SAF-T',
                'alternate' => 'Standard Audit File for Tax',
                'description' => 'International (OECD) standard for a standardised tax audit file, designed to ease audits by exporting accounting data in a common XML format. In Luxembourg, the FAIA is the version required by the AED.',
            ],
            'ubl' => [
                'name' => 'UBL',
                'alternate' => 'Universal Business Language',
                'description' => 'Open XML standard (OASIS) defining electronic business documents (invoice, credit note, purchase order). The Peppol BIS format used for e-invoicing in Europe is based on UBL 2.1.',
            ],
            'zugferd' => [
                'name' => 'ZUGFeRD',
                'alternate' => 'Hybrid PDF/XML invoice (Germany)',
                'description' => 'German hybrid e-invoice format combining a human-readable PDF/A with embedded structured XML data. It shares the same standard (EN 16931) as the Franco-German Factur-X, with which it is largely interoperable.',
            ],
            'aed' => [
                'name' => 'AED',
                'alternate' => 'Administration de l\'Enregistrement, des Domaines et de la TVA',
                'description' => 'Luxembourg tax authority responsible for VAT, registration of deeds and inheritance duties. It conducts tax audits and is the recipient of the FAIA audit file.',
            ],
            'autoliquidation' => [
                'name' => 'Reverse charge',
                'alternate' => 'Intra-EU B2B VAT reverse charge (autoliquidation)',
                'description' => 'Mechanism whereby, for services supplied between taxable persons in two EU member states, VAT is not charged by the supplier but self-assessed by the customer in their own country. The invoice bears the "Reverse charge" mention. Legal basis: article 17 LIVA (place of supply) and article 196 of Directive 2006/112/EC (person liable for VAT).',
            ],
            'franchise_tva' => [
                'name' => 'VAT exemption scheme',
                'alternate' => 'Small business franchise regime',
                'description' => 'Scheme for taxable persons whose annual turnover does not exceed EUR 50,000 excl. VAT (threshold in force since 2025, with a 10% tolerance for exceeding it). Under this scheme the business charges no VAT and cannot deduct it on purchases. An exemption mention must appear on every invoice (regime set out in articles 57 et seq. LIVA).',
            ],
            'numerotation_sequentielle' => [
                'name' => 'Sequential numbering',
                'alternate' => 'Mandatory continuous invoice numbering',
                'description' => 'Requirement to give every invoice a unique, sequential and continuous number, in an unbroken chronological series. A gap or duplicate in the numbering can trigger a tax adjustment under the presumption of undeclared turnover. Legal basis: article 63 LIVA.',
            ],
            'ccss' => [
                'name' => 'CCSS',
                'alternate' => 'Joint Social Security Centre - Luxembourg',
                'description' => 'Luxembourg body managing social security affiliations for employees and self-employed workers. Every sole trader must register with the CCSS at incorporation and declare income for social contribution calculation.',
            ],
            'factur_x' => [
                'name' => 'Factur-X',
                'alternate' => 'Hybrid PDF/A-3 + XML CII format',
                'description' => 'European electronic invoice standard combining a human-readable PDF/A-3 and an embedded XML file (UN/CEFACT Cross Industry Invoice) readable by accounting software. Lets you send a single invoice readable by both sides.',
            ],
            // FAIA Export
    'faia' => [
                'name' => 'FAIA',
                'alternate' => 'Standard Audit File of the Luxembourg tax authority',
                'description' => 'Structured XML file based on the OECD SAF-T standard and published by the AED in version 2.01, which gathers all of a company\'s accounting data over a given period. The AED may require its production during a tax audit; it has been the pivot of every VAT review since 2020.',
            ],
            'liva' => [
                'name' => 'LIVA',
                'alternate' => 'Luxembourg VAT law',
                'description' => 'Law of 12 February 1979 as amended, governing VAT in Luxembourg: tax liability, rates, mandatory mentions on invoices, reverse charge, exemption regimes. The most cited articles are 21 (reverse charge), 56 ter (exemption) and 61 (numbering).',
            ],
            'oss' => [
                'name' => 'OSS',
                'alternate' => 'One Stop Shop - EU VAT single window',
                'description' => 'EU scheme effective since 1 July 2021 allowing a business to declare and pay VAT due in several member states via a single window, when its cross-border B2C sales exceed the EUR 10,000 annual threshold.',
            ],
            'pdf_a' => [
                'name' => 'PDF/A',
                'alternate' => 'Long-term archive format - ISO 19005',
                'description' => 'Normalised PDF variant dedicated to long-term archiving: embedded fonts, no scripts, no broken external links. It is the format required by Article 16 of the Luxembourg Code of Commerce for the 10-year retention of invoices.',
            ],
            'peppol' => [
                'name' => 'Peppol',
                'alternate' => 'Pan-European Public Procurement OnLine',
                'description' => 'International standardised electronic invoicing network for exchanging structured invoices (UBL or CII) between businesses and public administrations. Mandatory in Luxembourg for B2G invoicing since 2023. A Luxembourg draft law of July 2026 provides for its extension to domestic B2B from 2028, and the ViDA directive to intra-EU B2B from 1 July 2030.',
            ],
            'rcs' => [
                'name' => 'RCS',
