    'legal_terms_s1_title' => '1. Purpose',
    'legal_terms_s1_p1' => 'These Terms and Conditions of Use and Sale (hereinafter "T&Cs") define the conditions under which Alexandre Beaudier, operator of the faktur.lu service (hereinafter "the Provider"), supplies users (hereinafter "the User" or "the Customer") with an online invoicing service.',
    'legal_terms_s1_p2' => 'Registration and use of the service imply full and unconditional acceptance of these T&Cs.',

    'legal_terms_s2_title' => '2. Definitions',
    'legal_terms_s2_li1_label' => 'Service:',
    'legal_terms_s2_li1_text' => 'The faktur.lu web application enabling the creation and management of invoices, quotes, credit notes and time tracking.',
    'legal_terms_s2_li2_label' => 'User / Customer:',
    'legal_terms_s2_li2_text' => 'Any natural or legal person who has created an account on faktur.lu.',
    'legal_terms_s2_li3_label' => 'Account:',
    'legal_terms_s2_li3_text' => 'The User\'s personal area accessible via their login credentials.',
    'legal_terms_s2_li4_label' => 'Subscription:',
    'legal_terms_s2_li4_text' => 'Paid plan giving access to extended features of the Service.',
    'legal_terms_s2_li5_label' => 'Content:',
    'legal_terms_s2_li5_text' => 'Data entered by the User (invoices, customers, etc.).',

    'legal_terms_s3_title' => '3. Access to the service',
    'legal_terms_s3_1_title' => '3.1 Registration',
    'legal_terms_s3_1_p' => 'Access to the Service requires the creation of an account. The User must provide accurate and complete information, including a valid email address.',
    'legal_terms_s3_2_title' => '3.2 Eligibility conditions',
    'legal_terms_s3_2_p' => 'The Service is intended for professionals (companies, freelancers, liberal professions). The User declares:',
    'legal_terms_s3_2_li1' => 'To be of legal age and legally capable',
    'legal_terms_s3_2_li2' => 'To be acting in the course of their professional activity',
    'legal_terms_s3_2_li3' => 'To have the necessary authorisations to use the Service',
    'legal_terms_s3_3_title' => '3.3 Account security',
    'legal_terms_s3_3_p' => 'The User is responsible for the confidentiality of their login credentials. Any use of their account is deemed to have been made by them. They must immediately inform faktur.lu of any unauthorised use.',

    'legal_terms_s4_title' => '4. Service description',
    'legal_terms_s4_p' => 'faktur.lu is an online invoicing software (SaaS) compliant with Luxembourg and European requirements, offering in particular:',
    'legal_terms_s4_li1' => 'Creation and management of invoices, quotes and credit notes',
    'legal_terms_s4_li2' => 'Customer and contact management',
    'legal_terms_s4_li3' => 'FAIA export compliant with AED Luxembourg',
    'legal_terms_s4_li4' => 'Time tracking and invoice generation',
    'legal_terms_s4_li5' => 'Sending invoices by email',
    'legal_terms_s4_li6' => 'Dashboard and statistics',
    'legal_terms_s4_li7' => 'Secure accountant access',

    'legal_terms_s5_title' => '5. Subscriptions and pricing',
    'legal_terms_s5_1_title' => '5.1 Subscription plans',
    'legal_terms_s5_1_p' => 'The Service offers several plans:',
    'legal_terms_s5_plan1_title' => 'Discovery (Free)',
    'legal_terms_s5_plan1_desc' => 'Limited features, ideal for trying out the service.',
    'legal_terms_s5_plan2_title' => 'Professional',
    'legal_terms_s5_plan2_desc' => 'Full features for freelancers and SMEs. Price shown on the pricing page.',
    'legal_terms_s5_2_title' => '5.2 Pricing',
    'legal_terms_s5_2_p1' => 'Prices are shown in euros excluding tax (excl. VAT) on the site. The applicable VAT will be added at the time of payment according to the rate in force in Luxembourg (17%).',
    'legal_terms_s5_2_p2' => 'The Provider reserves the right to change its prices at any time. Price changes will be notified by email at least 30 days before they come into effect and will apply to the next subscription renewal.',
    'legal_terms_s5_3_title' => '5.3 Duration and renewal',
    'legal_terms_s5_3_p' => 'Subscriptions are taken out for a monthly or annual term at the User\'s choice. They are automatically renewed by tacit agreement at the end of each period, unless terminated in accordance with article 13.',
    'legal_terms_s5_4_title' => '5.4 Trial period',
    'legal_terms_s5_4_p' => 'A free trial period may be offered. At the end of this period, the subscription becomes chargeable unless cancelled. The User will be informed before the end of the trial period.',

    'legal_terms_s6_title' => '6. Payment',
    'legal_terms_s6_1_title' => '6.1 Payment methods',
    'legal_terms_s6_1_p' => 'Payment is made by credit card (Visa, Mastercard, American Express) via the secure Stripe platform. Transactions are encrypted and compliant with PCI-DSS standards.',
    'legal_terms_s6_2_title' => '6.2 Invoicing',
    'legal_terms_s6_2_p' => 'An electronic invoice is issued and available in the customer area after each payment. It can also be sent by email upon request.',
    'legal_terms_s6_3_title' => '6.3 Payment default',
    'legal_terms_s6_3_p' => 'In the event of payment failure, the User will be notified and will have 7 days to regularise. After this period, access to paid features will be suspended. Data will be kept for an additional 30 days before any deletion.',
    'legal_terms_s6_4_title' => '6.4 VAT',
    'legal_terms_s6_4_p' => 'For professional customers established in another EU Member State holding a valid intra-Community VAT number, VAT will not be charged (reverse charge). The Customer will then need to declare the VAT in their country.',

    'legal_terms_s7_title' => '7. Right of withdrawal',
    'legal_terms_s7_warn_title' => 'Important information for consumers',
    'legal_terms_s7_warn_p' => 'In accordance with article L. 221-28 of the French Consumer Code and equivalent provisions of Luxembourg law, the right of withdrawal does not apply to contracts for the supply of digital content not supplied on a tangible medium where performance has begun with the consumer\'s express prior consent.',
    'legal_terms_s7_p1' => 'By taking out a paid subscription, the User acknowledges that:',
    'legal_terms_s7_li1' => 'They expressly request immediate performance of the service',
    'legal_terms_s7_li2' => 'They expressly waive their 14-day right of withdrawal as soon as access to the paid service is activated',
    'legal_terms_s7_p2' => 'However, for annual subscriptions, a prorata temporis refund may be granted upon request within the first 30 days following the subscription, subject to reasonable use of the service.',

    'legal_terms_s8_title' => '8. User obligations',
    'legal_terms_s8_p' => 'The User undertakes to:',
    'legal_terms_s8_li1' => 'Provide accurate information upon registration and keep it up to date',
    'legal_terms_s8_li2' => 'Use the Service for its intended purpose (professional invoicing)',
    'legal_terms_s8_li3' => 'Not to use the Service for unlawful purposes or contrary to public order',
    'legal_terms_s8_li4' => 'Maintain the confidentiality of their login credentials',
    'legal_terms_s8_li5' => 'Comply with the tax and accounting legislation applicable to their activity',
    'legal_terms_s8_li6' => 'Not attempt to compromise the security or operation of the Service',
    'legal_terms_s8_li7' => 'Not to resell or sublicense access to the Service',

    'legal_terms_s9_title' => '9. faktur.lu obligations',
    'legal_terms_s9_1_title' => '9.1 Service availability',
    'legal_terms_s9_1_p1' => 'The Provider undertakes to implement the necessary means to ensure the availability of the Service 24/7, with a target availability of 99.5% (excluding scheduled maintenance).',
    'legal_terms_s9_1_p2' => 'Maintenance interruptions will, as far as possible, be scheduled outside business hours and announced in advance.',
    'legal_terms_s9_2_title' => '9.2 Support',
    'legal_terms_s9_2_p_before' => 'Technical support is available by email at',
    'legal_terms_s9_2_p_after' => '. Response time varies depending on the subscription plan.',
    'legal_terms_s9_3_title' => '9.3 Security and backup',
    'legal_terms_s9_3_p' => 'The Provider implements security measures in accordance with industry standards and performs regular data backups.',

    'legal_terms_s10_title' => '10. Data and ownership',
    'legal_terms_s10_1_title' => '10.1 Data ownership',
    'legal_terms_s10_1_p' => 'The User remains the owner of all data they enter into the Service (invoices, customer information, etc.). The Provider acquires no rights to this data.',
    'legal_terms_s10_2_title' => '10.2 Usage licence',
    'legal_terms_s10_2_p' => 'The User grants the Provider a limited licence to process their data solely in the context of providing the Service.',
    'legal_terms_s10_3_title' => '10.3 Data export',
    'legal_terms_s10_3_p' => 'The User can export their data at any time in standard formats (PDF, CSV, FAIA XML).',
    'legal_terms_s10_4_title' => '10.4 Data protection',
    'legal_terms_s10_4_p_before' => 'The processing of personal data is governed by our',
    'legal_terms_s10_4_link' => 'Privacy policy',
    'legal_terms_s10_4_p_after' => '.',

    'legal_terms_s10_5_title' => '10.5 GDPR data processing (DPA)',
    'legal_terms_s10_5_p_before' => 'When the User acts as data controller under Regulation (EU) 2016/679 (GDPR) and faktur.lu processes personal data on their behalf, the parties agree that the ',
    'legal_terms_s10_5_link' => 'Data Processing Agreement (DPA)',
    'legal_terms_s10_5_p_after' => ', available at any time on the website, forms an integral part of these Terms. By accepting the Terms, the User also accepts the DPA in its current version. A separate handwritten signature can be provided on request for Users who need it for their own compliance (notably fiduciaries and clients subject to audit).',

    'legal_terms_s11_title' => '11. Intellectual property',
    'legal_terms_s11_p1' => 'The Service, including its source code, interface, features, design, trademarks and logos, is the exclusive property of the Provider or its partners.',
    'legal_terms_s11_p2' => 'The subscription grants only a personal, non-exclusive and non-transferable right to use the Service for the duration of the subscription.',

    'legal_terms_s12_title' => '12. Limitation of liability',
    'legal_terms_s12_1_title' => '12.1 Warranties',
    'legal_terms_s12_1_p' => 'The Provider undertakes to provide the Service diligently. However, the Service is provided "as is" and the Provider does not guarantee that it will meet all the User\'s specific needs.',
    'legal_terms_s12_2_title' => '12.2 Limitation',
    'legal_terms_s12_2_p1' => 'The Provider\'s liability is limited to direct damages and may not exceed the amount of sums paid by the User during the last 12 months.',
    'legal_terms_s12_2_p2' => 'The Provider cannot be held responsible for:',
    'legal_terms_s12_2_li1' => 'Indirect damages (loss of turnover, commercial loss, etc.)',
    'legal_terms_s12_2_li2' => 'The accuracy of the data entered by the User',
    'legal_terms_s12_2_li3' => 'The tax compliance of invoices issued by the User',
    'legal_terms_s12_2_li4' => 'Interruptions due to third parties (hosting provider, ISP, etc.)',
    'legal_terms_s12_2_li5' => 'Cases of force majeure',
    'legal_terms_s12_3_title' => '12.3 User liability',
    'legal_terms_s12_3_p' => 'The User is solely responsible for the compliance of their invoices with the applicable tax regulations. The Service is a tool facilitating invoicing but does not constitute tax or legal advice.',

    'legal_terms_s13_title' => '13. Termination',
    'legal_terms_s13_1_title' => '13.1 Termination by the User',
    'legal_terms_s13_1_p1' => 'The User can cancel their subscription at any time from their customer area. The cancellation will take effect at the end of the current period. The User retains access to the Service until that date.',
    'legal_terms_s13_1_p2' => 'Sums already paid are non-refundable, unless otherwise provided for in article 7.',
    'legal_terms_s13_2_title' => '13.2 Termination by the Provider',
    'legal_terms_s13_2_p' => 'The Provider may terminate the subscription in the event of:',
    'legal_terms_s13_2_li1' => 'Breach of these T&Cs',
    'legal_terms_s13_2_li2' => 'Unsettled payment default',
    'legal_terms_s13_2_li3' => 'Fraudulent or abusive use of the Service',
    'legal_terms_s13_2_li4' => 'Discontinuation of the Service (with 3 months\' notice)',
    'legal_terms_s13_3_title' => '13.3 Consequences of termination',
    'legal_terms_s13_3_p' => 'Upon termination, the User has 30 days to export their data. After this period, the data may be deleted, subject to legal retention obligations.',

    'legal_terms_s14_title' => '14. Modifications to the T&Cs',
    'legal_terms_s14_p1' => 'The Provider reserves the right to modify these T&Cs. Modifications will be notified by email and/or by display on the Service at least 30 days before they come into effect.',
    'legal_terms_s14_p2' => 'Continued use of the Service after the modifications come into effect constitutes acceptance of the new T&Cs. In case of disagreement, the User may terminate their subscription.',

    'legal_terms_s15_title' => '15. Applicable law and jurisdiction',
    'legal_terms_s15_p1' => 'These T&Cs are governed by Luxembourg law.',
    'legal_terms_s15_p2' => 'In the event of a dispute, the parties will endeavour to find an amicable solution. Failing that, the courts of Luxembourg shall have exclusive jurisdiction.',
    'legal_terms_s15_p3_label' => 'Mediation:',
    'legal_terms_s15_p3_text' => 'In accordance with European regulations, in the event of an unresolved dispute, the consumer may use the mediation service free of charge. Online dispute resolution platform:',

