    'legal_cookies_s1_p1' => 'A cookie is a small text file placed on your device (computer, tablet, smartphone) when you visit a website. It allows the site to remember information about your visit, such as your language preferences or login status.',
    'legal_cookies_s1_p2' => 'Cookies can be placed by the site you visit ("first-party cookies") or by third-party services ("third-party cookies").',
